def transform(grid):
    """Compare panels on either side of a solid divider; mark aligned cells of their shared color."""
    h, w = len(grid), len(grid[0])
    if any(len(row) != w for row in grid):
        raise ValueError('Grid must be rectangular')
    panels = []
    for r in range(h):
        if len(set(grid[r])) == 1:
            panels.append((grid[:r], grid[r + 1:]))
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            panels.append(([row[:c] for row in grid], [row[c + 1:] for row in grid]))
    for first, second in panels:
        if not first or not second or len(first) != len(second) or len(first[0]) != len(second[0]):
            continue
        shared = {v for row in first for v in row} & {v for row in second for v in row}
        if len(shared) == 1:
            common = next(iter(shared))
            return [[3 if a == b == common else common for a, b in zip(ra, rb)]
                    for ra, rb in zip(first, second)]
    raise ValueError('No equal-sized panels with one shared color')
